css:
:scope { width: min(100%, 914px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 12 / span 12; grid-row: 1 / span 44; aspect-ratio: 468 / 351; }
.gx__i2 { grid-column: 4 / span 4; grid-row: 8 / span 3; font-family: var(--os-font-label); font-size: 14.6px; font-weight: 600; line-height: 1.1; letter-spacing: 0.3em; text-transform: uppercase; text-align: center; color: inherit; }
.gx__i3 { grid-column: 1 / span 10; grid-row: 15 / span 13; font-family: var(--os-font-heading); font-size: 23px; font-weight: 400; line-height: 1.5; letter-spacing: 0em; text-align: center; color: var(--os-color-heading); }
.gx__i4 { grid-column: 3 / span 4; grid-row: 32 / span 5; font-family: var(--os-font-label); font-size: 12.3px; font-weight: 400; line-height: 1.2; letter-spacing: 0.1em; text-transform: uppercase; text-align: center; color: var(--os-color-background); }
.gx__i4 { justify-self: center; }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i2 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i3 { font-family: var(--os-font-heading); font-size: 18px; }
  .gx__i4 { font-family: var(--os-font-label); font-size: 14px; }
}
